/* ================= cart ================= */
const COUPONS={};   /* cache dos cupons já validados pelo back-end: { TECH10: 0.1 } */

/* Pergunta ao back-end se o cupom existe (GET /api/coupons/:code). */
async function aplicarCupom(v,quiet){
  let r={valid:false};
  if(v){try{r=await (await fetch('/api/coupons/'+encodeURIComponent(v))).json()}catch(e){}}
  if(r.valid){COUPONS[r.code]=r.percent;coupon=r.code}else coupon='';
  save();renderCart();
  if(!r.valid&&!quiet){const m=$('cpmsg');if(m){m.className='msg err';m.textContent=v?`O cupom ${v} não existe. Experimente TECH10.`:'Digite um cupom.'}}
}

/* Envia o pedido ao back-end (POST /api/orders). O front manda só ids e
   quantidades; o back-end recalcula preços e descontos e devolve o total real. */
let enviando=false;
async function finalizarPedido(){
  if(enviando) return; enviando=true;
  try{
    const r=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({items:cart,coupon,payment:pay})});
    const d=await r.json();
    if(!r.ok) throw new Error(d.error||'Erro ao finalizar o pedido.');
    done={code:d.code,pay,total:d.total};cart={};coupon='';save();renderCart();
  }catch(e){toast(e.message||'Não foi possível finalizar o pedido.')}
  finally{enviando=false}
}
let done=null;
function totals(){
  const ids=Object.keys(cart).filter(id=>byId[id]&&cart[id]>0);
  const sub=ids.reduce((s,id)=>s+byId[id].price*cart[id],0);
  let kit=0;KITS.forEach(k=>{const n=Math.min(...k.items.map(id=>cart[id]||0));if(n>0)kit+=k.items.reduce((a,id)=>a+byId[id].price,0)*n*0.05});kit=Math.round(kit*100)/100;
  const cp=COUPONS[coupon]?Math.round((sub-kit)*COUPONS[coupon]*100)/100:0;
  const after=sub-kit-cp;
  const pixOff=pay==='pix'?Math.round(after*0.1*100)/100:0;
  const ship=sub===0||sub>=299?0:29.9;
  return {ids,sub,kit,cp,pixOff,ship,total:after-pixOff+ship,n:ids.reduce((s,id)=>s+cart[id],0)};
}
function renderCart(){
  const t=totals();
  $('cartN').textContent=t.n;
  if(done){
    $('items').innerHTML=`<div class="done-box"><span class="promo">Pedido feito!</span><span>Pedido de demonstração <code>${done.code}</code> · total ${brl(done.total)}</span><span>${done.pay==='pix'?'O QR Code do PIX apareceria aqui.':'O pagamento em 10x seria processado aqui.'} Nenhuma cobrança foi feita.</span><button class="btn" type="button" data-close>Continuar comprando</button></div>`;
    $('sum').innerHTML='';return;
  }
  if(!t.ids.length){
    $('items').innerHTML='<div class="cartempty"><span>Seu carrinho está vazio.</span><button class="btn volt" type="button" data-tab="ofertas" data-close>Ver ofertas</button></div>';
    $('sum').innerHTML='';return;
  }
  $('items').innerHTML=t.ids.map(id=>{const p=byId[id],q=cart[id];return `<div class="line">
    <div class="mini" style="background:${D[p.cat].tint}">${ICON[D[p.cat].ic]}</div>
    <div class="nm">${esc(p.name)}</div><div class="pr">${brl(p.price*q)}</div>
    <div class="ctl"><div class="qty"><button type="button" data-dec="${id}" aria-label="Diminuir">−</button><span>${q}</span><button type="button" data-inc="${id}" aria-label="Aumentar">+</button></div><button class="rm" type="button" data-rm="${id}">Remover</button></div><div></div></div>`}).join('');
  $('sum').innerHTML=`
    <div class="coupon"><input id="cp" placeholder="Cupom" value="${esc(coupon)}" aria-label="Cupom de desconto"><button type="button" data-coupon>Aplicar</button></div>
    <div class="msg ${coupon&&COUPONS[coupon]?'ok':''}" id="cpmsg">${coupon&&COUPONS[coupon]?'Cupom '+coupon+' aplicado: 10% off.':''}</div>
    <div class="pay"><button type="button" data-pay="pix" aria-pressed="${pay==='pix'}">PIX<small>10% off</small></button><button type="button" data-pay="card" aria-pressed="${pay==='card'}">Cartão<small>até 10x sem juros</small></button></div>
    <div class="r"><span>Subtotal (${t.n} ${t.n===1?'item':'itens'})</span><span>${brl(t.sub)}</span></div>
    ${t.kit?`<div class="r disc"><span>Kit de upgrade (5%)</span><span>−${brl(t.kit)}</span></div>`:''}
    ${t.cp?`<div class="r disc"><span>Cupom ${coupon}</span><span>−${brl(t.cp)}</span></div>`:''}
    ${t.pixOff?`<div class="r disc"><span>Desconto PIX</span><span>−${brl(t.pixOff)}</span></div>`:''}
    <div class="r"><span>Frete</span><span>${t.ship?brl(t.ship):'Grátis'}</span></div>
    <div class="r big"><span>Total</span><span>${brl(t.total)}</span></div>
    ${pay==='card'?`<div class="spec">10x de ${brl(t.total/10)} sem juros</div>`:''}
    <button class="btn volt block" type="button" data-checkout>Finalizar pedido</button>`;
}
function add(id,q=1){cart[id]=(cart[id]||0)+q;done=null;save();renderCart();const b=$('openCart');b.classList.remove('bump');void b.offsetWidth;b.classList.add('bump')}
const openCart=()=>{screenEl.classList.remove('modal-open');screenEl.classList.add('cart-open')};
const closeAll=()=>{screenEl.classList.remove('cart-open','modal-open');if(done){done=null;renderCart()}};
let tt;function toast(m){const el=$('toast');el.textContent=m;el.classList.add('on');clearTimeout(tt);tt=setTimeout(()=>el.classList.remove('on'),1800)}

/* ================= events ================= */
document.addEventListener('click',e=>{
  const t=e.target.closest('button,[data-open]'); if(!t) return;
  const ds=t.dataset;
  if(ds.tscroll){const tb=$('tabs');tb.scrollBy({left:(+ds.tscroll)*tb.clientWidth*0.6,behavior:'smooth'});return}
  if('promo' in ds){const p=PROMOS[+ds.promo];go(p.go.tab,{pid:p.go.pid,sale:p.go.sale});return}
  if(ds.add){e.stopPropagation();add(ds.add);t.classList.add('done');t.textContent='Adicionado ✓';setTimeout(()=>{t.classList.remove('done');t.textContent='Adicionar ao carrinho'},1200);toast(byId[ds.add].name+' no carrinho');return}
  if(ds.tab){closeAll();go(ds.tab);return}
  if(ds.open){openProduct(ds.open);return}
  if('close' in ds){closeAll();return}
  if('more' in ds){st.limit+=24;render(true);return}
  if(ds.kit!==undefined){KITS[+ds.kit].items.forEach(id=>add(id));toast(KITS[+ds.kit].name+' no carrinho');openCart();return}
  if(ds.facet){st.limit=24;const f=ds.facet,v=ds.val;const a=st.f[f]||(st.f[f]=[]);const i=a.indexOf(v);i<0?a.push(v):a.splice(i,1);render(true);return}
  if('sale' in ds){st.sale=!st.sale;render(true);return}
  if('clear' in ds){st.f={};st.sale=false;render(true);return}
  if(ds.mq){mQty=Math.max(1,Math.min(9,mQty+(+ds.mq)));$('mq').textContent=mQty;return}
  if('madd' in ds){add(mId,mQty);toast(`${mQty}× ${byId[mId].name} no carrinho`);screenEl.classList.remove('modal-open');return}
  if('mbuy' in ds){add(mId,mQty);openCart();return}
  if(ds.inc){add(ds.inc);return}
  if(ds.dec){cart[ds.dec]--;if(cart[ds.dec]<=0)delete cart[ds.dec];save();renderCart();return}
  if(ds.rm){delete cart[ds.rm];save();renderCart();return}
  if('coupon' in ds){aplicarCupom($('cp').value.trim().toUpperCase());return}
  if(ds.pay){pay=ds.pay;save();renderCart();return}
  if('checkout' in ds){finalizarPedido();return}
  if(t.id==='openCart'){openCart();return}
});
