/* tab slider: a draggable bar under the tabs, plus arrows and wheel */
function syncTrack(){
  const tb=$('tabs'), tr=$('ttrack'), th=$('tthumb'); if(!tb||!tr) return;
  const max=tb.scrollWidth-tb.clientWidth;
  $('ttwrap').hidden=max<=2; $('tprev').disabled=tb.scrollLeft<=1; $('tnext').disabled=tb.scrollLeft>=max-1;
  if(max<=2) return;
  const W=tr.clientWidth, w=Math.max(28, W*tb.clientWidth/tb.scrollWidth);
  th.style.width=w+'px'; th.style.left=(tb.scrollLeft/max*(W-w))+'px';
}
$('tabs').addEventListener('scroll',syncTrack,{passive:true});
$('tabbar').addEventListener('wheel',e=>{const tb=$('tabs');const d=Math.abs(e.deltaX)>Math.abs(e.deltaY)?e.deltaX:e.deltaY;if(tb.scrollWidth>tb.clientWidth){e.preventDefault();tb.scrollLeft+=d}},{passive:false});
(function(){
  const tb=$('tabs'), tr=$('ttrack'), th=$('tthumb'); let drag=null;
  const ratio=()=>{const W=tr.clientWidth,w=th.offsetWidth;return (tb.scrollWidth-tb.clientWidth)/Math.max(1,W-w)};
  th.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();drag={x:e.clientX,l:tb.scrollLeft};th.classList.add('drag');th.setPointerCapture(e.pointerId)});
  th.addEventListener('pointermove',e=>{if(!drag)return;tb.scrollLeft=drag.l+(e.clientX-drag.x)*ratio()});
  const end=()=>{drag=null;th.classList.remove('drag')};
  th.addEventListener('pointerup',end); th.addEventListener('pointercancel',end);
  tr.addEventListener('pointerdown',e=>{if(e.target===th)return;const r=tr.getBoundingClientRect(),w=th.getBoundingClientRect().width;
    const f=Math.min(1,Math.max(0,(e.clientX-r.left-w/2)/Math.max(1,r.width-w)));tb.scrollTo({left:f*(tb.scrollWidth-tb.clientWidth),behavior:'smooth'})});
})();

/* countdowns */
const BF=new Date('2026-11-27T00:00:00-03:00').getTime();
const pad=n=>String(n).padStart(2,'0');
function tick(){
  const now=Date.now();
  let s=Math.max(0,Math.floor((BF-now)/1000));
  const d=Math.floor(s/86400); s%=86400;
  $('bfcd').textContent=`${d}d ${pad(Math.floor(s/3600))}:${pad(Math.floor(s%3600/60))}:${pad(s%60)}`;
  const mid=new Date();mid.setHours(24,0,0,0);
  let r=Math.max(0,Math.floor((mid-now)/1000));
  const f=$('flashcd'); if(f) f.textContent=`${pad(Math.floor(r/3600))}:${pad(Math.floor(r%3600/60))}:${pad(r%60)}`;
}
setInterval(tick,1000);

